<template><view class="page"><view class="row task-heading"><view><view class="title">今日任务</view><view class="muted">{{dateLabel}}</view></view><picker mode="date" :value="date" :start="plan?plan.startDate:undefined" :end="endDate" @change="setDate"><view class="calendar">▦</view></picker></view><view v-if="error" class="card"><view class="error">{{error}}</view><button class="secondary" @click="load">重新加载</button></view><view v-else-if="loading" class="loading">正在加载…</view><EmptyState v-else-if="!plan"/><template v-else><scroll-view class="filters" scroll-x><view class="filter-line"><view :class="['pill',subject===''?'active':'']" @click="subject=''">全部</view><view v-for="s in subjects" :key="s" :class="['pill',subject===s?'active':'']" @click="subject=s">{{s}}</view></view></scroll-view><view class="row status-row"><text class="muted">已完成 {{done}} / {{tasks.length}}</text><view class="row"><text :class="filter==='all'?'link':'muted'" @click="filter='all'">全部</text><text :class="filter==='pending'?'link':'muted'" @click="filter='pending'">未完成</text></view></view><view v-if="!visibleTasks.length" class="card empty"><view class="title">{{tasks.length?'暂无符合条件的任务':'这一天没有任务'}}</view><view class="muted">切换科目或日期查看学习安排。</view></view><view v-for="t in visibleTasks" :key="t.id" class="task-row" @click="toggle(t)"><view :class="['check',t.completed?'checked':'']">{{t.completed?'✓':''}}</view><view class="task-label"><view>{{t.subject}} · {{t.name}}</view></view><text class="duration">{{t.duration}}分钟</text></view><button class="primary add-plan" @click="create">＋ 新建备考计划</button><view class="row date-actions"><text class="link" @click="move(-1)">‹ 前一天</text><text class="link" @click="date=today();load()">回到今天</text><text class="link" @click="move(1)">后一天 ›</text></view><view class="muted foot">任务时长按计划预算分配，点击方框完成或撤销打卡。</view></template></view></template>
<script setup>
import {ref,computed} from 'vue';import {onShow} from '@dcloudio/uni-app';import {api,current,showError} from '../../api';import {today,addDays} from '../../utils/planner.mjs';import EmptyState from '../../components/EmptyState.vue'
const plan=ref(null),tasks=ref([]),date=ref(today()),loading=ref(true),error=ref(''),busy=ref(''),filter=ref('all'),subject=ref('')
const subjects=computed(()=>[...new Set(tasks.value.map(t=>t.subject))]),visibleTasks=computed(()=>tasks.value.filter(t=>(!subject.value||t.subject===subject.value)&&(filter.value==='all'||!t.completed))),done=computed(()=>tasks.value.filter(t=>t.completed).length),endDate=computed(()=>plan.value?addDays(plan.value.examDate,-1):today()),dateLabel=computed(()=>{const d=new Date(date.value+'T00:00:00Z');return date.value.replace('-','年').replace('-','月')+'日　周'+['日','一','二','三','四','五','六'][d.getUTCDay()]})
async function load(){loading.value=true;error.value='';try{plan.value=await current();tasks.value=plan.value?await api.tasks(plan.value.id,date.value):[];if(subject.value&&!subjects.value.includes(subject.value))subject.value=''}catch(e){error.value=e.message}finally{loading.value=false}}
async function toggle(t){if(busy.value)return;busy.value=t.id;try{await api.complete(t.id,!t.completed);t.completed=!t.completed}catch(e){showError(e)}finally{busy.value=''}}
function move(n){const next=addDays(date.value,n);if(next<plan.value.startDate||next>endDate.value)return;date.value=next;load()}function setDate(e){date.value=e.detail.value;load()}function create(){uni.navigateTo({url:'/pages/exam/create'})}onShow(()=>{const s=uni.getStorageSync('dkm-task-subject');if(typeof s==='string')subject.value=s;uni.removeStorageSync('dkm-task-subject');load()})
</script>
<style scoped>.task-heading{margin:6rpx 0 26rpx}.title{font-size:43rpx}.task-heading .muted{font-size:24rpx;margin-top:5rpx}.calendar{font-size:46rpx;color:#1B3C31;padding:4rpx 10rpx}.filters{white-space:nowrap;width:100%;margin-bottom:22rpx}.filter-line{display:inline-flex;gap:20rpx;padding:3rpx 0 10rpx}.pill{padding:9rpx 28rpx;background:#F0F4F2;color:#213C31;border-radius:40rpx;font-size:25rpx;font-weight:650}.pill.active{background:linear-gradient(110deg,#1BB496,#0CBC7D);color:white;box-shadow:0 5rpx 15rpx #12AD8222}.status-row{margin-bottom:20rpx}.status-row .muted,.status-row .link{font-size:21rpx}.status-row .row{gap:16rpx}.task-row{display:flex;gap:20rpx;align-items:center;padding:27rpx 22rpx;background:linear-gradient(110deg,#fff,#F9FCFA);border-radius:20rpx;margin-bottom:18rpx;min-height:110rpx}.task-label{flex:1;font-size:27rpx;font-weight:600;min-width:0}.duration{color:#7C9088;font-size:24rpx;white-space:nowrap}.add-plan{margin-top:28rpx}.date-actions{margin:26rpx 2rpx}.date-actions .link{font-size:22rpx}.foot{font-size:21rpx;text-align:center}</style>
<style scoped>.page{padding-top:calc(28rpx + env(safe-area-inset-top))}</style>
<style scoped>
/* #ifdef MP-WEIXIN */
.page{padding-top:calc(94rpx + env(safe-area-inset-top))}
/* #endif */
</style>
